import 'bootstrap/dist/css/bootstrap.min.css';
import "./DXNavigationHeaderMobile.scss";

import React, { ReactElement, useState } from 'react';
import { NavigationProps } from "../DXNavigationHeader/DXNavigationHeader";

import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import Form from 'react-bootstrap/Form';
import InputGroup from 'react-bootstrap/InputGroup';
import DXButton from "../DXButton/DXButton";
import { getLinkTarget, getLinkIcon, getIcon } from "../../utilities";

export interface MobileNavigationProps extends NavigationProps {
    headerHeight?: string;
    icons?: {
        search?: string;
        navigationFoward?: string;
        navigationBack?: string;
        close?: string;
        menu?: string;
    };
}

export interface NavigationItem {
    title: string;
    url?: string;
    target?: string;
    children?: NavigationItem[];
    index: number;
}

export interface NavigationNode {
    id: string;
    parent: ReactElement;
    children?: NavigationNode[];
    level: number;
    index: number;
}

let generateElementByLevel = ( item: NavigationItem, level: number ): ReactElement<any, string> => {

    let onClickFunction: () => void = () => {};
    let itemClass: string = "";

    switch ( level ) {
        case 1: {
            itemClass = `mobile-primary-navigation-${item.index}-${item.title}`;
            onClickFunction = function () {
                if ( item.children ) {
                    const itemNode: NavigationNode = {
                        id: item.title,
                        level: level,
                        parent: generateElementByLevel( item, level ),
                        index: item.index,
                        children: processItems( item.children, level + 1 )
                    };
                    setPrimarySelected( itemNode );
                    setSecondaryLevel( [...item.children] );
                }
            };

            break;
        }
        case 2: {
            itemClass = `mobile-secondary-navigation-${item.index}-${item.title}`;
            onClickFunction = function () {
                if ( item.children ) {
                    const itemNode: NavigationNode = {
                        id: item.title,
                        level: level,
                        parent: generateElementByLevel( item, level ),
                        index: item.index,
                        children: processItems( item.children, level + 1 )
                    };
                    setSecondarySelected( itemNode );
                    setThirdLevel( [...item.children] );
                }
            };
            break;
        }

        case 3: {
            itemClass = `mobile-third-navigation-${item.index}-${item.title}`;
            break;
        }

        default: {
            return <div>NO DATA</div>;
        }
    }
    let navigationItem = (
        <li key={"primary-navigation-" + item.index} className={"dxNavHeaderMobile__primaryItem _18-semibold "}
            onClick={() => { onClickFunction(); }} >
            < span className={"dxNavHeaderMobile__itemBorder "}></span>
            < a className={"dxNavHeaderMobile__itemContent _18-semibold " + ( level == 1 ? "with_border" : "" )}
                href={( item.url && !item.children ) ? item.url : undefined}
                target={getLinkTarget( item.target )}
            >
                <p>{item.title}</p>
                {getLinkIcon( item.target )}
                {
                    item.children &&
                    <i className={`${getIcon( properties.icons, "navigationFoward", "ci-Chevron_Right" )} chevron`}></i>
                }
            </a >
        </li>
    );

    return navigationItem;
};

let processItems = ( items: NavigationItem[], level: number ): NavigationNode[] => {
    let itemsTree: NavigationNode[] = [];
    items.forEach( ( item: NavigationItem ) => {
        const itemNode: NavigationNode = {
            id: item.title,
            level: level,
            parent: generateElementByLevel( item, level ),
            index: item.index
        };
        if ( item.children ) {
            itemNode.children = processItems( item.children, level + 1 );
        }
        itemsTree.push( itemNode );
    } );
    return itemsTree;
};

let renderSecondaryLevel = (): ReactElement[] => {
    let secondaryLevelItems: ReactElement[] = [];
    secondaryLevelItems.push(
        <li data-testid="second-return-item" key={"primary-navigation-top"} className={"dxNavHeaderMobile__primaryItem _18-semibold "}
            onClick={() => {
                setSecondaryLevel( [] );
            }} >
            < span className={"dxNavHeaderMobile__itemBorder "}></span>
            < a className={"dxNavHeaderMobile__itemContent back _18-semibold "}>
                <i className={getIcon( properties.icons, "navigationBack", "ci-Chevron_Left" )}></i>
                <p>Go Back to {primarySelected.id}</p>
            </a >
        </li>
    );
    if ( primarySelected.children ) {
        primarySelected.children.forEach( ( item: NavigationNode ) => {
            secondaryLevelItems.push( item.parent );
        } );
    }

    return secondaryLevelItems;
};

let renderThirdLevel = (): ReactElement[] => {
    let secondaryLevelItems: ReactElement[] = [];
    secondaryLevelItems.push(
        <li data-testid="third-return-item" key={"primary-navigation-top"} className={"dxNavHeaderMobile__primaryItem _18-semibold "}
            onClick={() => {
                setThirdLevel( [] );
            }} >
            < span className={"dxNavHeaderMobile__itemBorder "}></span>
            < a className={"dxNavHeaderMobile__itemContent return-item back _18-semibold "}>
                <i className={getIcon( properties.icons, "navigationBack", "ci-Chevron_Left" )}></i>
                <p>Go Back to {secondarySelected.id}</p>
            </a >
        </li>
    );
    if ( secondarySelected.children ) {
        secondarySelected.children.forEach( ( item: NavigationNode ) => {
            secondaryLevelItems.push( item.parent );
        } );
    }

    return secondaryLevelItems;
};

//HOOKS
var searchIsActive: boolean;
var setSearchActive: React.Dispatch<React.SetStateAction<boolean>>;
var menuIsActive: boolean;
var setMenuActive: React.Dispatch<React.SetStateAction<boolean>>;
var secondaryActive: NavigationItem[];
var setSecondaryLevel: React.Dispatch<React.SetStateAction<NavigationItem[]>>;
var primarySelected: NavigationNode;
var setPrimarySelected: React.Dispatch<React.SetStateAction<NavigationNode>>;
var thirdActive: NavigationItem[];
var setThirdLevel: React.Dispatch<React.SetStateAction<NavigationItem[]>>;
var secondarySelected: NavigationNode;
var setSecondarySelected: React.Dispatch<React.SetStateAction<NavigationNode>>;

let properties: MobileNavigationProps;
const DXNavigationHeaderMobile = ( props: MobileNavigationProps ) => {
    properties = props;
    document.documentElement.style.setProperty( '--headerHeight', props.headerHeight || "80px" );

    //Initializing Hooks
    let aux: NavigationItem[] = [];
    let emptyNavNode: NavigationNode = {
        id: "",
        parent: <></>,
        level: -1,
        index: -1
    };
    [searchIsActive, setSearchActive] = useState( false );
    [menuIsActive, setMenuActive] = useState( false );
    [secondaryActive, setSecondaryLevel] = useState( aux );
    [thirdActive, setThirdLevel] = useState( aux );
    [primarySelected, setPrimarySelected] = useState( emptyNavNode );
    [secondarySelected, setSecondarySelected] = useState( emptyNavNode );
    //END Hook Initializing

    let children: NavigationNode[] = [];
    if ( props.navigationItems ) {
        children = ( processItems( props.navigationItems, 1 ) );
    }
    let primaryLevel: ReactElement[] = [];
    let secondaryLevels: NavigationNode[][] = [];

    children.forEach( ( node ) => {
        if ( node.level == 1 && node.parent ) {
            primaryLevel.push( node.parent );
        }
        if ( node.children ) {
            secondaryLevels.push( node.children );
        } else {
            secondaryLevels.push( [] );
        }

    } );
    return (
        <div className="dxNavHeaderMobile">
            <Container fluid="xl" data-testid="menu-container" className={menuIsActive ? "active" : "hidden"}>
                <Row className="dxNavHeaderMobile__topRow justify-content-between">
                    {/* Menu button-icon */}
                    <Col xs={1} className={"dxNavHeaderMobile__headerCol active"}>
                        <DXButton
                            label="menu"
                            hideLabel
                            displayType="unstyled"
                            className="dxNavHeaderMobile__headerButton align-right"
                            data-testid="menu-button"
                            onClick={() => {
                                if ( !( menuIsActive || searchIsActive ) ) {
                                    setMenuActive( true );
                                    document.getElementsByTagName( "body" )[0].classList.add( "dxNavHeaderMobile--scrolling-stop" );
                                    window.scrollTo( 0, 0 );
                                    setSearchActive( true );
                                } else {
                                    document.getElementsByTagName( "body" )[0].classList.remove( "dxNavHeaderMobile--scrolling-stop" );
                                    setMenuActive( false );
                                    setSearchActive( false );
                                    setSecondaryLevel( [] );
                                    setThirdLevel( [] );
                                }
                            }}
                            icon={{
                                class: ( menuIsActive || searchIsActive ) ? getIcon( props.icons, "close", "ci-Close_MD" ) : getIcon( props.icons, "menu", "ci-Hamburger_LG" )
                            }}
                        />
                    </Col>
                    {/* Header image container */}
                    <Col xs={10} className={"dxNavHeaderMobile__headerCol " + ( searchIsActive ? "" : "active" )}>
                        <div className='dxNavHeaderMobile__headerImage'>
                            <img src={props.navigationImage}
                                alt={props.navigationImageAlt ? props.navigationImageAlt : "Header Image"}
                                height={props.navigationImageHeight ? props.navigationImageHeight : 25}
                                width={props.navigationImageWidth ? props.navigationImageWidth : 195}
                            >
                            </img>
                        </div>
                    </Col>
                    {/* Search button-icon */}
                    <Col xs={1} className={"dxNavHeaderMobile__headerCol " + ( searchIsActive ? "" : "active" )}>
                        <DXButton
                            label="search icon"
                            hideLabel
                            data-testid="search-show"
                            displayType="unstyled"
                            className="dxNavHeaderMobile__headerButton"
                            onClick={() => {
                                setSearchActive( true );
                            }}
                            icon={{
                                class: getIcon( props.icons, "search", "ci-Search_Magnifying_Glass" )
                            }} />
                    </Col>
                    {/* Navigation Search Input container */}
                    <Col data-testid="search-container" xs={11} className={"dxNavHeaderMobile__searchCol " + ( searchIsActive ? "active" : "" )}>
                        <Form onSubmit={props.searchSubmit}>
                            <Form.Group className='dxNavHeaderMobile__search' onSubmit={() => {}} >
                                <InputGroup>
                                    <div className="input-group-item input-group-prepend">
                                        <Form.Control className="dxNavHeaderMobile__searchInput" placeholder="Search this site" type="text" />
                                    </div>
                                    <div className={"input-group-inset-item dxNavHeaderMobile__searchButton"}>
                                        <DXButton
                                            label="search icon"
                                            hideLabel
                                            data-testid="search-button"
                                            displayType="unstyled"
                                            type="submit"
                                            icon={{
                                                class: getIcon( props.icons, "search", "ci-Search_Magnifying_Glass" )
                                            }} />
                                    </div>
                                </InputGroup>
                            </Form.Group>
                        </Form>
                    </Col>
                </Row>
                <Row className={"dxNavHeaderMobile__menuRow " + ( menuIsActive ? "active" : "" )}>
                    <Col data-testid="first-level-column" className={"dxNavHeaderMobile__navigationCol primary " + ( menuIsActive ? "active" : "" ) + ( secondaryActive.length ? " hidden" : "" )} xs={12}>
                        <ul className="dxNavHeaderMobile__itemContainer">
                            {primaryLevel}
                        </ul>
                    </Col>
                    <Col xs={12} data-testid="second-level-column" className={"dxNavHeaderMobile__navigationCol secondary " + ( ( secondaryActive.length && !( thirdActive.length ) ) ? "active" : "" ) + ( !secondaryActive.length || thirdActive.length ? " hidden" : "" )}>
                        <ul className="dxNavHeaderMobile__itemContainer">
                            {renderSecondaryLevel()}
                        </ul>
                    </Col>
                    <Col xs={12} data-testid="third-level-column" className={"dxNavHeaderMobile__navigationCol secondary " + ( thirdActive.length ? "active" : "" )}>
                        <ul className="dxNavHeaderMobile__itemContainer">
                            {renderThirdLevel()}
                        </ul>
                    </Col>
                </Row>
            </Container>
        </div>
    );
};

export default DXNavigationHeaderMobile;
